import type { ServiceVarConfig } from "@/lib/db/schema";
import type { ServiceValues } from "./preview-ready";

/**
 * The two env files a developer works with. `.env.example` holds names only and belongs in the
 * repository; `.env.local` holds this machine's values and must never be committed. Both come from
 * the same list Saqina sends to the deployment, so the app reads the same names everywhere.
 */

interface Named {
  provider: string;
  label: string;
  vars: Pick<ServiceVarConfig, "name" | "secret">[];
}

const HEADER = [
  "# Generated by Saqina Dev from the project's databases and sign-in services.",
  "# Live and Preview values are set on the deployment by Saqina; this file is for your machine.",
];

export function renderEnvExample(services: Named[]): string {
  const lines = [
    ...HEADER,
    "# Copy to .env.local and fill in, or download .env.local from Studio.",
    "",
  ];
  for (const s of services) {
    lines.push(`# ${s.label} (${s.provider})`);
    for (const v of s.vars) lines.push(`${v.name}=`);
    lines.push("");
  }
  return lines.join("\n");
}

/** Double-quoted, with backslashes, quotes and line breaks escaped, as dotenv reads it. */
export const quoteEnv = (value: string) =>
  `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\r?\n/g, "\\n")}"`;

/**
 * `.env.local` for a developer's machine: the local value of each variable, or the preview's when
 * there is none. The live value is never written here.
 */
export function renderEnvLocal(services: ServiceValues[]): string {
  const lines = [...HEADER, "# Do not commit this file.", ""];
  const seen = new Set<string>();
  for (const s of services) {
    lines.push(`# ${s.label} (${s.provider})`);
    for (const v of s.vars) {
      const value = s.development[v.name] || s.preview[v.name];
      if (seen.has(v.name)) lines.push(`# ${v.name} is also set above; this one wins.`);
      seen.add(v.name);
      lines.push(
        value ? `${v.name}=${quoteEnv(value)}` : `# ${v.name}= (no local or preview value yet)`,
      );
    }
    lines.push("");
  }
  return lines.join("\n");
}

const NAME = /^\s*(?:export\s+)?([A-Z][A-Z0-9_]*)\s*=/;

/** Variable names in a `.env.example` text; comments and blank lines are skipped. */
export function parseEnvNames(text: string): string[] {
  const names = new Set<string>();
  for (const line of text.split(/\r?\n/)) {
    if (/^\s*#/.test(line)) continue;
    const m = NAME.exec(line);
    if (m) names.add(m[1]);
  }
  return [...names];
}

export interface EnvGap {
  /** Named in the repository's `.env.example` but not set up in Saqina: the preview may break. */
  missingInSaqina: string[];
  /** Set up in Saqina but not listed in the repository's `.env.example`. */
  missingInRepo: string[];
}

/** Platform variables a Next.js app on Vercel gets by itself; never asked of the person. */
const PROVIDED = /^(NODE_ENV|VERCEL|VERCEL_.*|NEXT_RUNTIME|PORT|CI)$/;

export function compareEnv(repoNames: string[], saqinaNames: string[]): EnvGap {
  const saqina = new Set(saqinaNames);
  const repo = new Set(repoNames);
  return {
    missingInSaqina: repoNames.filter((n) => !saqina.has(n) && !PROVIDED.test(n)).sort(),
    missingInRepo: saqinaNames.filter((n) => !repo.has(n)).sort(),
  };
}
